D.RULES = {
  { "h2", "How to play" },
  {
    "p",
    "Go down floor after floor through a dungeon that never ends. Every floor is new, and the monsters get stronger the deeper you go. When you're defeated, you keep all the gold you found and spend it at camp on upgrades, so your next run can go deeper. The goal is to beat your deepest floor.",
  },
  { "h3", "The map" },
  { "li", "@ is you (the black square)." },
  {
    "li",
    "Two-letter codes are monsters, like RT Rat, GB Goblin, TR Troll. A few have three, like SC2 Scorpion. A code on a black square is a boss. A code with a double border is a champion, which carries treasure.",
  },
  { "li", "> stairs down, E elevator." },
  { "li", "$ gold, ! potion, ? scroll, * treasure chest (gold and a potion or scroll)." },
  { "li", "& merchant, + shrine, \" relic (a free perk), { enchanting table, p pet." },
  { "li", "Floor dangers: ~ lava, ^ spikes, : poison gas, # shock floor. These hurt when you step on them." },
  {
    "li",
    "Other floors: % mushroom (heals you), = water, web, mud or sand (slows you), - ice (you slide), O portal (jumps you to the other portal).",
  },
  { "li", "x with a dotted border: a bomb or falling rock lands there next turn. Step off it!" },
  { "li", "Dark gray squares are walls. Light gray squares are places you've seen but can't see right now." },
  { "h3", "Moving and fighting" },
  {
    "p",
    "Use the arrow buttons, or tap a square next to you. Step into a monster to attack it. Every time you act, each awake monster also gets a turn. Nobody can attack diagonally.",
  },
  {
    "p",
    "Tap a square farther away that you've already seen, and you walk all the way there in one tap. This works even with monsters around. You stop as soon as something hits or hurts you, when you level up, or when you step on something to choose (a merchant, a shrine).",
  },
  { "p", "Wait skips your turn, which is handy for letting a monster come to you." },
  {
    "p",
    "Messages under the map tell you what happened. When a lot happens in one turn, they turn into a Combat log: a list of everything, in order (like \"The Goblin attacks for 6 damage.\", \"Poison deals 2 damage.\", \"Your pet heals you for 4 HP.\", \"You defeat the Goblin and gain 12 XP.\"), with your HP before and after at the bottom.",
  },
  { "h3", "Weapons" },
  { "p", "There are 300 weapons in 10 families. Each family fights differently:" },
  { "li", "Sword: +5% critical. Dagger: +15% critical, a bit weaker. Axe: extra damage." },
  {
    "li",
    "Bow: tap a monster up to 4 squares away in a straight line to shoot it. Firearm: the same, up to 5 squares.",
  },
  { "li", "Staff: shoots 3 squares and ignores armor. Spear: reaches a monster 2 squares away." },
  {
    "li",
    "Hammer: big damage, 15% chance to stun. Scythe: hits every monster next to you at once. Exotic: 20% chance to hit twice.",
  },
  { "p", "Every weapon has a modifier in its name, like \"Flaming Moonblade\" or \"Rusty Skullsplitter\":" },
  {
    "li",
    "Sharp: 15% chance of +50% damage. Dull: weaker, but 20% chance to stun. Rusty: weaker, but 20% chance to make the monster bleed.",
  },
  { "li", "Leeching: heals you on every hit. Flaming: 25% chance to burn. Frozen: 20% chance to slow the monster." },
  {
    "li",
    "Shocking: 15% chance that half the damage jumps to a nearby monster. Heavy: stronger, can knock monsters back, but some swings are slow.",
  },
  {
    "li",
    "Swift: weaker, but can hit again or give you a free turn. Cursed: stronger, with a 10% chance of double damage that also costs you a little HP.",
  },
  {
    "li",
    "From floor 8, rarer ones appear: Poisoned, Vampiric, Explosive, Piercing, Lucky, Unstable, Blessed (extra damage to undead), Spectral, Regenerating and Echoing.",
  },
  {
    "p",
    "Weapons and armor also have a rarity: Common, Uncommon, Rare, Epic, Legendary, Mythic, Ancient, Celestial and Cosmic. Rarer gear has more bonuses. You can't find weapons or armor in the dungeon: buy them in the Weapon shop and Armor shop at camp. Chests, bosses and champions give potions and scrolls instead.",
  },
  { "h3", "Monsters" },
  {
    "p",
    "There are 10,000 monsters: 100 kinds, and every 100 floors a new, tougher version of every kind appears with 2 extra traits (like the Frost Rat, the Storm Goblin or the Iron Troll). There are 100 kinds of monsters. New kinds keep appearing as you go deeper, all the way past floor 50. Each kind has its own tricks: archers and mages shoot from a distance, ghosts float through walls, slimes split, healers heal other monsters, bombardiers throw bombs, burrowers hide underground, and shapeshifters pretend to be gold. The list under the map tells you what every monster you can see does.",
  },
  {
    "p",
    "Deeper monsters are also born with extra random traits, like Swift, Venomous, Armored or Explosive. New traits unlock as you go down, and the deepest monsters get several at once. Bosses come every 5 floors, each with its own name.",
  },
  { "h3", "Floors" },
  {
    "p",
    "Every 10 floors you enter a new zone with its own kind of map: rooms, caves, a maze or pillared halls. There are 1,000 zones (10,000 floors!), each with its own dangers and monsters: frozen caverns with slippery ice, burning mines full of lava, haunted halls where you can only see 2 squares, and many more. After all 1,000 they come back tougher as \"II\", then \"III\", and so on.",
  },
  {
    "p",
    "Every floor has its own floor type: 10,000 of them, one for each floor from 1 to 10,000, shown at the top. Each one is one of 50 kinds of floors plus a word and an ending that change it, like \"Glittering Library of Champions\" (extra gold, scrolls and a champion) or \"Icy Spider Den of Shadows\" (ice, webs, spiders and darkness). Some of the 50 kinds:",
  },
  { "li", "Treasure Vault, Library, Armory, Mimic Gallery, Relic Chamber: extra loot of one kind." },
  { "li", "Spider Den, Goblin Warrens, Skeleton Crypt, Rat King's Sewers: lots of one family of monsters." },
  { "li", "Spike Maze, Burning Foundry, Frozen Labyrinth, Poison Garden, Collapsing Mine: floor dangers." },
  {
    "li",
    "Mirror Hall (the map is mirrored), Portal Nexus, Observatory (the whole map is shown), Enchanter's Workshop.",
  },
  {
    "li",
    "Boss Lair, Colosseum, The King's Court and Dragon's Hoard on boss floors, and The Dungeon Core every 50 floors.",
  },
  { "li", "There's also a very rare secret floor. Good luck finding it!" },
  {
    "p",
    "Below the map, About this floor explains what the current floor does, what each kind of floor square does, and every kind of monster on the floor and its tricks, even the ones you haven't seen yet.",
  },
  {
    "p",
    "A merchant sells a potion and scrolls for the gold you've found this run. A shrine lets you heal fully, or gain a random perk and lose some HP. An enchanting table gives your weapon a new random modifier. If you walk off one without choosing, step back on it or tap yourself while standing on it.",
  },
  { "h3", "Classes" },
  {
    "p",
    "At camp, Classes opens the class list: 300 classes in 10 tiers, from Beginners up to Ultimate. Buy any class in any order with your camp gold, and equip any class you own (one at a time). Switching between classes you own is free, and classes stay yours forever, even after you ascend. Each class shows its description and an \"In this game\" line saying exactly what it does here, like more damage, defense or HP, crits, dodge, more gold, stronger pets, shields, saving you from defeat, or powers that freeze or blast monsters every few turns. Everyone starts as a Novice.",
  },
  { "h3", "Pets" },
  {
    "p",
    "There are 10,000 pets, from Common to Mythical. Look for p on the map: some floors have a pet waiting, nests and breeding grounds have more, and bosses sometimes have one hiding with them.",
  },
  {
    "p",
    "When you find a pet, the game tells you if it's a GOOD ADDITION or a BAD ADDITION to your team, and why. You can have up to 5 pets on your team. Only team pets help you in the dungeon. Every pet you find is kept in your collection at camp, so you never lose one. Finding a pet you already have makes it level up, up to level 5 (about 3 in 10 pets you find are ones you already have).",
  },
  {
    "p",
    "Some pets fight: they bite, blast, zap or freeze monsters every few turns. Others protect you (blocking hits, saving you from defeat, teleporting you to safety), heal you, let you see farther or show hidden monsters, or bring more gold. Each pet's card says what it does in the pet book, and \"In this game\" says exactly what it does here. At camp, Manage pets lets you change your team.",
  },
  { "h3", "Bounties" },
  {
    "p",
    "Every floor has a bounty, shown under the messages, like \"Defeat 2 Goblins\", \"Open a treasure chest\" or \"Reach the stairs within 30 turns\". Finish it for extra gold, and sometimes a scroll.",
  },
  { "h3", "Levels and perks" },
  {
    "p",
    "Defeating monsters earns experience. Each level gives more max HP, +1 attack, and heals you a bit. Every 2 levels you choose one of three random perks, like Vampire, Critical, Thorns or Nimble. The same perk can be picked more than once.",
  },
  {
    "p",
    "Perks are saved by level. The perk you choose at level 2 is saved for level 2. In every later run, you get it automatically as soon as you reach level 2 again, but not before. At camp, Saved perks lists them all. Tap Change on one to choose again.",
  },
  { "h3", "Potions and scrolls" },
  { "li", "Potion: heals half your max HP and cures poison." },
  { "li", "Fire scroll: burns every monster you can see." },
  { "li", "Freeze scroll: monsters you can see stop moving for 3 turns." },
  { "li", "Teleport scroll: jumps you to a random spot far away. Great for escaping." },
  { "li", "Map scroll: shows the whole floor, including the stairs." },
  {
    "p",
    "Drinking or reading uses your turn. You can be Poisoned (lose HP each turn), Weak (less attack) or Slowed (monsters get extra steps). These wear off after a few turns.",
  },
  { "h3", "The elevator" },
  {
    "p",
    "Every floor has an elevator E right where you arrive. Stand on it and tap Elevator (or tap yourself) to pick any floor from 1 down to your deepest. At camp you can also start a run on any floor you've reached. Starting deeper gives you free levels, perks and gear.",
  },
  { "h3", "Camp" },
  {
    "li",
    "Upgrades last forever: max HP, attack, armor, starting potions, starting scrolls, and Blessing (extra perks at the start of every run).",
  },
  {
    "li",
    "Encyclopedia (at camp, or at the bottom of the screen during a run) lists every enemy, weapon, modifier, monster trait, floor type, zone, perk, scroll and map symbol. The ones you've found are marked.",
  },
  {
    "li",
    "Collection shows how many of the 100 monsters, 300 weapons, 20 modifiers and 50 kinds of floors you've found, and how many of the 10,000 unique floors you've visited.",
  },
  {
    "li",
    "Weapon shop: 5,000 weapons you can buy with gold. Weapons you buy are yours forever, even after you ascend. Equip one and it's your starting weapon on every run, until you buy or pick a different one. Tap Best I can afford to jump to the strongest one you can buy. Weapons and armor can't be found in the dungeon: the shops are the only way to get better gear.",
  },
  {
    "li",
    "Armor shop: 1,000 armors that work just like the weapon shop. Armor you buy is yours forever. Equip one and it's your starting armor on every run, until you buy or pick a different one.",
  },
  {
    "li",
    "Achievements: there are 1,008 of them, and they never run out. Tap Achievements at camp to see them in sections: Monster Hunting, Monster Traits, Weapons, Gear, Floors and Zones, Floor Dangers, Pets, Classes, Perks and Levels, Items and Places, Combat, Bounties, Bosses and Adventure. Every achievement has endless levels. After level V, each new level needs twice as much, and every level pays more gold. New levels are paid when you get back to camp.",
  },
  {
    "li",
    "Ascend: when you get stuck, you can start over from floor 1 with your gold, upgrades and deepest floor reset. In return you earn stars (1 for every 5 floors past floor 20 on your deepest-ever floor). Each star gives +10% attack, HP and gold forever, so every time you ascend you can go deeper than before. Saved perks, achievements and your collection stay.",
  },
  { "h3", "Saving" },
  {
    "p",
    "The game saves after every move, even in the middle of a run. If your Kindle clears its saved data, you'd lose progress, so open Save code at camp now and then and copy the code somewhere safe. Paste it back in to restore everything.",
  },
  {
    "p",
    "To start completely over, use Reset all progress at the bottom of camp. You have to tap it twice, so it can't happen by accident.",
  },
  { "h3", "Tips" },
  { "li", "Fight in corridors so only one monster can reach you at a time." },
  { "li", "Against monsters that shoot, get close fast or stay out of their line." },
  { "li", "With a bow, staff, spear or firearm, attack monsters before they reach you." },
  { "li", "Watch for x squares and step off them." },
  { "li", "Save Fire and Teleport scrolls for emergencies, like a boss or a crowd." },
  { "h3", "Characters" },
  { "p", "At camp, tap Characters and spend gold to summon a random character. You never get the same one twice, and there are 10,000. Rarer ones (Common, Uncommon, Rare, Epic, Legendary, Mythic) are harder to get and stronger. Up to 4 go in your party (tap Best party to pick your 4 strongest), and they stay yours forever, even after you ascend." },
  { "p", "In the dungeon one character is active. Tap Switch to change who's active at any time: it doesn't use a turn. The active character adds to your attack and uses its talent, like freezing monsters, hitting twice or healing. Every character in the party adds to your max HP." },
  { "p", "Every character has its own burst: a big move like a meteor, a shield, a poison cloud or a teleport. Bursts need energy. Your active character gets energy when you hit monsters, defeat them, or get hit; the others in the party get half. Each character needs a different amount. When the bar is full, tap Burst. Info shows every party member's talent, burst and energy." },
  { "h3", "Artifacts" },
  { "p", "Treasure chests also hold an artifact you don't have yet. There are 50,000, in 7 rarities (Common, Uncommon, Rare, Epic, Legend, Mythic and Godly), and deeper floors give rarer ones. You keep them forever." },
  { "p", "Each character wears one of each piece: a Flower, a Plume, a Sands, a Goblet and a Circlet, so a party of 4 wears up to 20. Equip them at camp: tap Characters, then Artifacts on a party member, or Best artifacts to dress the whole party at once." },
  { "p", "Every artifact has a main stat and, if it's rare enough, extra stats. ATK, DEF, Crit, Dodge and Gold work while that character is active. HP adds to the whole party's max HP. Energy fills that character's burst faster, and Burst makes it hit harder." },
}

